{
  "name": "Calc3D - Precificador de Impressão 3D",
  "description": "Uma calculadora profissional para precificação de serviços de impressão 3D, considerando custos de material, energia, falhas, embalagem e taxas de marketplace."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface PlatformPreset {
  name: string;
  percentage: number;
  fixedFee: number;
}

export interface CalculationInputs {
  weightGrams: number;
  pricePerKilo: number;
  printTimeHours: number;
  powerConsumptionWatts: number;
  energyCostKwh: number;
  packagingCost: number;
  failureRate: number;
  extraCosts: number;
  profitMargin: number;
  platformPercentage: number;
  platformFixedFee: number;
}

export interface CalculationResults {
  materialCost: number;
  energyCost: number;
  baseProductionCost: number;
  costWithFailure: number;
  netPrice: number;
  platformFeeAmount: number;
  finalSellingPrice: number;
  profitAmount: number;
}

import React from 'react';

interface InputFieldProps {
  label: string;
  value: number;
  onChange: (val: number) => void;
  prefix?: string;
  suffix?: string;
  step?: number;
  min?: number;
  tooltip?: string;
}

export const InputField: React.FC<InputFieldProps> = ({
  label,
  value,
  onChange,
  prefix,
  suffix,
  step = 0.01,
  min = 0,
  tooltip
}) => {
  return (
    <div className="flex flex-col gap-1 w-full">
      <label className="text-sm font-medium text-slate-700 flex items-center gap-2">
        {label}
        {tooltip && (
          <span className="text-xs text-slate-400 cursor-help" title={tooltip}>ⓘ</span>
        )}
      </label>
      <div className="relative flex items-center">
        {prefix && (
          <span className="absolute left-3 text-slate-400 text-sm">{prefix}</span>
        )}
        <input
          type="number"
          value={value}
          step={step}
          min={min}
          onChange={(e) => onChange(parseFloat(e.target.value) || 0)}
          className={`w-full bg-white border border-slate-200 rounded-lg py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all ${
            prefix ? 'pl-8' : 'pl-3'
          } ${suffix ? 'pr-8' : 'pr-3'}`}
        />
        {suffix && (
          <span className="absolute right-3 text-slate-400 text-sm">{suffix}</span>
        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip as RechartsTooltip, Legend } from 'recharts';
import { 
  Calculator, 
  Printer, 
  Package, 
  Zap, 
  AlertTriangle, 
  TrendingUp, 
  Share2, 
  Download,
  Info
} from 'lucide-react';
import { InputField } from './components/InputField';
import { CalculationInputs, CalculationResults, PlatformPreset } from './types';
import { PLATFORM_PRESETS, DEFAULT_INPUTS } from './constants';

const App: React.FC = () => {
  const [inputs, setInputs] = useState<CalculationInputs>(DEFAULT_INPUTS);
  const [selectedPlatform, setSelectedPlatform] = useState<string>(PLATFORM_PRESETS[0].name);

  // Core Calculation Logic
  const results = useMemo((): CalculationResults => {
    const materialCost = (inputs.weightGrams / 1000) * inputs.pricePerKilo;
    const energyCost = (inputs.printTimeHours * (inputs.powerConsumptionWatts / 1000)) * inputs.energyCostKwh;

    // Total raw production cost (Material + Energy + Packaging + Extras)
    const baseProductionCost = materialCost + energyCost + inputs.packagingCost + inputs.extraCosts;

    // Adjust for failure rate: if 10% fail, effective cost is divided by 0.9
    const costWithFailure = inputs.failureRate >= 100 ? baseProductionCost : baseProductionCost / (1 - (inputs.failureRate / 100));

    // Net price after production cost + profit margin (Margin on cost)
    // Formula: Price = Cost * (1 + Margin/100)
    const netPrice = costWithFailure * (1 + (inputs.profitMargin / 100));

    // Final Selling Price considering Platform Fees
    // Formula: (NetPrice + FixedFee) / (1 - (PercentageFee / 100))
    // This ensures we get the desired netPrice even after platform deductions.
    const finalSellingPrice = (netPrice + inputs.platformFixedFee) / (1 - (inputs.platformPercentage / 100));

    const platformFeeAmount = finalSellingPrice - netPrice;
    const profitAmount = netPrice - costWithFailure;

    return {
      materialCost,
      energyCost,
      baseProductionCost,
      costWithFailure,
      netPrice,
      platformFeeAmount,
      finalSellingPrice,
      profitAmount
    };
  }, [inputs]);

  const handleInputChange = (field: keyof CalculationInputs, value: number) => {
    setInputs(prev => ({ ...prev, [field]: value }));
  };

  const handlePlatformChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const preset = PLATFORM_PRESETS.find(p => p.name === e.target.value);
    if (preset) {
      setSelectedPlatform(preset.name);
      if (preset.name !== 'Personalizado') {
        setInputs(prev => ({
          ...prev,
          platformPercentage: preset.percentage,
          platformFixedFee: preset.fixedFee
        }));
      }
    }
  };

  // Chart Data
  const chartData = [
    { name: 'Material', value: results.materialCost, color: '#3b82f6' },
    { name: 'Energia', value: results.energyCost, color: '#f59e0b' },
    { name: 'Embalagem', value: inputs.packagingCost, color: '#10b981' },
    { name: 'Extras', value: inputs.extraCosts, color: '#6366f1' },
    { name: 'Custo Falhas', value: results.costWithFailure - results.baseProductionCost, color: '#ef4444' },
    { name: 'Taxas Plataforma', value: results.platformFeeAmount, color: '#94a3b8' },
    { name: 'Lucro Líquido', value: results.profitAmount, color: '#8b5cf6' },
  ].filter(item => item.value > 0);

  const formatBRL = (val: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg text-white">
              <Calculator size={24} />
            </div>
            <h1 className="text-xl font-bold text-slate-900 tracking-tight">
              Calc<span className="text-blue-600">3D</span>
            </h1>
          </div>
          <div className="flex gap-2">
            <button 
              onClick={() => window.print()}
              className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors"
            >
              <Download size={16} /> <span className="hidden sm:inline">Exportar</span>
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Inputs Section */}
          <div className="lg:col-span-2 space-y-6">

            {/* Filament & Print Section */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
              <div className="flex items-center gap-2 mb-6">
                <Printer className="text-blue-600" size={20} />
                <h2 className="text-lg font-semibold text-slate-800">Material e Impressão</h2>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <InputField 
                  label="Peso da Peça" 
                  value={inputs.weightGrams} 
                  onChange={(v) => handleInputChange('weightGrams', v)} 
                  suffix="g"
                />
                <InputField 
                  label="Preço do Filamento (kg)" 
                  value={inputs.pricePerKilo} 
                  onChange={(v) => handleInputChange('pricePerKilo', v)} 
                  prefix="R$"
                />
                <InputField 
                  label="Tempo de Impressão" 
                  value={inputs.printTimeHours} 
                  onChange={(v) => handleInputChange('printTimeHours', v)} 
                  suffix="h"
                />
                <InputField 
                  label="Taxa de Falha Estimada" 
                  value={inputs.failureRate} 
                  onChange={(v) => handleInputChange('failureRate', v)} 
                  suffix="%"
                  tooltip="Percentual médio de impressões que falham e precisam ser descartadas."
                />
              </div>
            </section>

            {/* Energy Section */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
              <div className="flex items-center gap-2 mb-6">
                <Zap className="text-yellow-500" size={20} />
                <h2 className="text-lg font-semibold text-slate-800">Consumo de Energia</h2>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <InputField 
                  label="Consumo da Impressora (Watts)" 
                  value={inputs.powerConsumptionWatts} 
                  onChange={(v) => handleInputChange('powerConsumptionWatts', v)} 
                  suffix="W"
                  tooltip="Consumo médio da máquina durante a impressão (ex: 150W)."
                />
                <InputField 
                  label="Custo do kWh" 
                  value={inputs.energyCostKwh} 
                  onChange={(v) => handleInputChange('energyCostKwh', v)} 
                  prefix="R$"
                  step={0.01}
                />
              </div>
            </section>

            {/* Platform & Post-Processing */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
              <div className="flex items-center gap-2 mb-6">
                <Package className="text-green-600" size={20} />
                <h2 className="text-lg font-semibold text-slate-800">Plataforma e Adicionais</h2>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-6">
                <InputField 
                  label="Custo Embalagem" 
                  value={inputs.packagingCost} 
                  onChange={(v) => handleInputChange('packagingCost', v)} 
                  prefix="R$"
                />
                <InputField 
                  label="Custos Avulsos" 
                  value={inputs.extraCosts} 
                  onChange={(v) => handleInputChange('extraCosts', v)} 
                  prefix="R$"
                  tooltip="Insumos extras como resina de pós-processamento, parafusos, imãs, etc."
                />
              </div>

              <div className="border-t border-slate-100 pt-6">
                <label className="text-sm font-medium text-slate-700 block mb-2">Canal de Venda / Categoria</label>
                <select 
                  value={selectedPlatform}
                  onChange={handlePlatformChange}
                  className="w-full bg-white border border-slate-200 rounded-lg py-2.5 px-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none mb-6"
                >
                  {PLATFORM_PRESETS.map(p => (
                    <option key={p.name} value={p.name}>{p.name}</option>
                  ))}
                </select>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                  <InputField 
                    label="Comissão Plataforma" 
                    value={inputs.platformPercentage} 
                    onChange={(v) => handleInputChange('platformPercentage', v)} 
                    suffix="%"
                  />
                  <InputField 
                    label="Taxa Fixa Plataforma" 
                    value={inputs.platformFixedFee} 
                    onChange={(v) => handleInputChange('platformFixedFee', v)} 
                    prefix="R$"
                  />
                </div>
              </div>
            </section>

            {/* Profit Margin */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
              <div className="flex items-center gap-2 mb-6">
                <TrendingUp className="text-purple-600" size={20} />
                <h2 className="text-lg font-semibold text-slate-800">Margem de Lucro</h2>
              </div>
              <div className="grid grid-cols-1 gap-6">
                <div>
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-sm text-slate-600">Margem de Lucro Desejada (sobre o custo)</span>
                    <span className="text-lg font-bold text-blue-600">{inputs.profitMargin}%</span>
                  </div>
                  <input 
                    type="range"
                    min="0"
                    max="300"
                    step="5"
                    value={inputs.profitMargin}
                    onChange={(e) => handleInputChange('profitMargin', parseInt(e.target.value))}
                    className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
                  />
                  <div className="flex justify-between text-[10px] text-slate-400 mt-2">
                    <span>0%</span>
                    <span>150%</span>
                    <span>300%</span>
                  </div>
                </div>
              </div>
            </section>
          </div>

          {/* Results Sidebar */}
          <div className="lg:col-span-1 space-y-6">

            {/* Main Result Card */}
            <div className="bg-blue-600 text-white p-8 rounded-3xl shadow-xl shadow-blue-200 sticky top-24">
              <p className="text-blue-100 text-sm font-medium uppercase tracking-wider mb-2">Preço Sugerido de Venda</p>
              <h3 className="text-4xl font-bold mb-6">{formatBRL(results.finalSellingPrice)}</h3>

              <div className="space-y-4 pt-6 border-t border-blue-400/30">
                <div className="flex justify-between text-sm">
                  <span className="text-blue-100">Custo Produção Total</span>
                  <span className="font-semibold">{formatBRL(results.costWithFailure)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-blue-100">Lucro Líquido (Real)</span>
                  <span className="font-semibold">{formatBRL(results.profitAmount)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-blue-100">Taxas Plataforma</span>
                  <span className="font-semibold">{formatBRL(results.platformFeeAmount)}</span>
                </div>
              </div>

              <div className="mt-8">
                <div className="bg-blue-700/50 p-4 rounded-xl flex items-start gap-3">
                  <AlertTriangle size={18} className="text-blue-200 mt-0.5" />
                  <p className="text-xs text-blue-50 leading-relaxed">
                    Este valor garante o pagamento de todas as taxas e mantém sua margem de lucro de 
                    <span className="font-bold"> {inputs.profitMargin}%</span> após os impostos do marketplace.
                  </p>
                </div>
              </div>
            </div>

            {/* Detailed Breakdown Card */}
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
              <h4 className="text-sm font-semibold text-slate-900 mb-6 flex items-center gap-2">
                <Info size={16} className="text-slate-400" />
                Composição de Custos
              </h4>

              <div className="h-64 w-full mb-6">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={chartData}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {chartData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Pie>
                    <RechartsTooltip 
                      formatter={(value: number) => formatBRL(value)}
                      contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                    />
                  </PieChart>
                </ResponsiveContainer>
              </div>

              <div className="space-y-3">
                {chartData.map((item) => (
                  <div key={item.name} className="flex items-center justify-between text-xs">
                    <div className="flex items-center gap-2">
                      <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: item.color }}></div>
                      <span className="text-slate-600">{item.name}</span>
                    </div>
                    <span className="font-medium text-slate-900">{formatBRL(item.value)}</span>
                  </div>
                ))}
              </div>
            </div>

            {/* Quick Tips */}
            <div className="bg-indigo-50 border border-indigo-100 p-6 rounded-2xl">
              <h4 className="text-sm font-semibold text-indigo-900 mb-2">Dica Pro</h4>
              <p className="text-xs text-indigo-700 leading-relaxed">
                Não esqueça de considerar o desgaste da impressora (manutenção) em "Custos Avulsos" se estiver realizando muitas horas de impressão para o mesmo cliente.
              </p>
            </div>

          </div>
        </div>
      </main>

      {/* Mobile Sticky CTA */}
      <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 p-4 lg:hidden shadow-lg z-20">
        <div className="flex justify-between items-center max-w-7xl mx-auto">
          <div>
            <p className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">Venda por:</p>
            <p className="text-xl font-bold text-blue-600">{formatBRL(results.finalSellingPrice)}</p>
          </div>
          <button className="bg-blue-600 text-white px-6 py-2.5 rounded-xl font-bold text-sm shadow-md shadow-blue-200 active:scale-95 transition-transform">
            Compartilhar Orçamento
          </button>
        </div>
      </div>
    </div>
  );
};

export default App;

