              className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-300 bg-slate-800 hover:bg-slate-700 rounded-lg transition-colors border border-slate-700"
            >
              <Download size={16} /> <span className="hidden sm:inline">Exportar</span>
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Inputs Section */}
          <div className="lg:col-span-2 space-y-6">

            {/* Filament & Print Section */}
            <section className="bg-slate-900 p-6 rounded-2xl shadow-xl border border-slate-800">
              <div className="flex items-center gap-2 mb-6 border-b border-slate-800 pb-4">
                <Printer className="text-blue-500" size={20} />
                <h2 className="text-lg font-semibold text-white">Material e Impressão</h2>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <InputField 
                  label="Peso da Peça" 
