const AppContent: React.FC = () => {
  const [inputs, setInputs] = useState<CalculationInputs>(DEFAULT_INPUTS);
  const [selectedPlatform, setSelectedPlatform] = useState<string>(PLATFORM_PRESETS[0].name);
  const location = useLocation();

  const results = useMemo((): CalculationResults => {
    const materialCost = (inputs.weightGrams / 1000) * inputs.pricePerKilo;
    const energyCost = (inputs.printTimeHours * (inputs.powerConsumptionWatts / 1000)) * inputs.energyCostKwh;
    const baseProductionCost = materialCost + energyCost + inputs.packagingCost + inputs.extraCosts;
    const costWithFailure = inputs.failureRate >= 100 ? baseProductionCost : baseProductionCost / (1 - (inputs.failureRate / 100));
    const netPrice = costWithFailure * (1 + (inputs.profitMargin / 100));
    const finalSellingPrice = (netPrice + inputs.platformFixedFee) / (1 - (inputs.platformPercentage / 100));
    const platformFeeAmount = finalSellingPrice - netPrice;
    const profitAmount = netPrice - costWithFailure;

    return {
      materialCost,
      energyCost,
      baseProductionCost,
      costWithFailure,
      netPrice,
      platformFeeAmount,
      finalSellingPrice,
      profitAmount
    };
  }, [inputs]);

  const handleInputChange = (field: keyof CalculationInputs, value: number) => {
    setInputs(prev => ({ ...prev, [field]: value }));
  };

  const handlePlatformChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const preset = PLATFORM_PRESETS.find(p => p.name === e.target.value);
