    { name: 'Embalagem', value: inputs.packagingCost, color: '#10b981' },
    { name: 'Extras', value: inputs.extraCosts, color: '#6366f1' },
    { name: 'Falhas', value: results.costWithFailure - results.baseProductionCost, color: '#ef4444' },
    { name: 'Taxas', value: results.platformFeeAmount, color: '#94a3b8' },
    { name: 'Lucro', value: results.profitAmount, color: '#8b5cf6' },
  ].filter(item => item.value > 0) : [];

  const formatBRL = (val: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
  };

  const CalculateButton = () => (
    <button 
      onClick={handleCalculate}
      className={`w-full flex items-center justify-center gap-3 py-5 rounded-2xl font-black text-lg transition-all shadow-xl active:scale-[0.98] ${
        isDirty 
          ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-blue-900/40 animate-pulse' 
          : 'bg-slate-800 text-slate-400 cursor-default border border-slate-700'
      }`}
    >
      <Play size={24} fill="currentColor" />
      {results ? 'Atualizar Cálculo' : 'Calcular Preço'}
    </button>
