    const preset = PLATFORM_PRESETS.find(p => p.percentage === inputs.platformPercentage && p.fixedFee === inputs.platformFixedFee);
    return preset ? preset.name : 'Personalizado';
  });

  const [results, setResults] = useState<CalculationResults | null>(null);
  const [isDirty, setIsDirty] = useState(true);
  const [isCalculating, setIsCalculating] = useState(false);
  const [calcKey, setCalcKey] = useState(0);
  const [copySuccess, setCopySuccess] = useState(false);

  const location = useLocation();

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(inputs));
  }, [inputs]);

  const handleCalculate = () => {
    setIsCalculating(true);
    // Simula um pequeno delay para feedback visual de "calculando"
    setTimeout(() => {
      const calculatedResults = runCalculation(inputs);
      setResults(calculatedResults);
      setIsDirty(false);
      setCalcKey(prev => prev + 1);
      setIsCalculating(false);
    }, 450);
