const STORAGE_KEY = 'calc3d_inputs';

/**
 * Componente animado para transição suave de valores monetários
 */
const AnimatedCurrency: React.FC<{ value: number }> = ({ value }) => {
  const [displayValue, setDisplayValue] = useState(value);
  const prevValueRef = useRef(value);

  useEffect(() => {
    const startValue = prevValueRef.current;
    const endValue = value;
    const duration = 600;
    let startTime: number | null = null;

    const animate = (currentTime: number) => {
      if (!startTime) startTime = currentTime;
      const progress = Math.min((currentTime - startTime) / duration, 1);
      const easedProgress = 1 - Math.pow(1 - progress, 3);
      const nextValue = startValue + (endValue - startValue) * easedProgress;
      setDisplayValue(nextValue);

      if (progress < 1) {
        requestAnimationFrame(animate);
      } else {
        prevValueRef.current = endValue;
      }
    };

    requestAnimationFrame(animate);
  }, [value]);

  return <span>{new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(displayValue)}</span>;
};

/**
 * Funções de utilidade para o cálculo de preços
 */
const calculateProductionCosts = (inputs: CalculationInputs) => {
  const materialCost = (inputs.weightGrams / 1000) * inputs.pricePerKilo;
  const energyCost = (inputs.printTimeHours * (inputs.powerConsumptionWatts / 1000)) * inputs.energyCostKwh;
  const baseProductionCost = materialCost + energyCost + inputs.packagingCost + inputs.extraCosts;
  return { materialCost, energyCost, baseProductionCost };
};

const applyFailureRate = (baseCost: number, rate: number) => {
  if (rate >= 100) return baseCost * 2;
  return baseCost / (1 - (rate / 100));
};

const calculateFinalPrice = (targetNetPrice: number, platformPct: number, fixedFee: number) => {
  const feeDecimal = platformPct / 100;
  if (feeDecimal >= 1) return targetNetPrice + fixedFee;
  return (targetNetPrice + fixedFee) / (1 - feeDecimal);
};

const runCalculation = (inputs: CalculationInputs): CalculationResults => {
  const { materialCost, energyCost, baseProductionCost } = calculateProductionCosts(inputs);
  const costWithFailure = applyFailureRate(baseProductionCost, inputs.failureRate);
  const netPrice = costWithFailure * (1 + (inputs.profitMargin / 100));
  const profitAmount = netPrice - costWithFailure;
  const finalSellingPrice = calculateFinalPrice(netPrice, inputs.platformPercentage, inputs.platformFixedFee);
  const platformFeeAmount = finalSellingPrice - netPrice;

  return {
    materialCost,
    energyCost,
    baseProductionCost,
    costWithFailure,
    netPrice,
    platformFeeAmount,
    finalSellingPrice,
    profitAmount
  };
};

