/**
 * Pure calculation logic optimized for performance
 */
const runCalculation = (inputs: CalculationInputs): CalculationResults => {
  const materialCost = (inputs.weightGrams / 1000) * inputs.pricePerKilo;
  const energyCost = (inputs.printTimeHours * (inputs.powerConsumptionWatts / 1000)) * inputs.energyCostKwh;
  const baseProductionCost = materialCost + energyCost + inputs.packagingCost + inputs.extraCosts;

  const failureRateDecimal = inputs.failureRate / 100;
  const costWithFailure = failureRateDecimal >= 1 
    ? baseProductionCost * 2 
    : baseProductionCost / (1 - failureRateDecimal);

  const netPrice = costWithFailure * (1 + (inputs.profitMargin / 100));
  const profitAmount = netPrice - costWithFailure;

  const platformFeeDecimal = inputs.platformPercentage / 100;
  const finalSellingPrice = platformFeeDecimal >= 1 
    ? netPrice + inputs.platformFixedFee 
    : (netPrice + inputs.platformFixedFee) / (1 - platformFeeDecimal);

  const platformFeeAmount = finalSellingPrice - netPrice;

  return {
    materialCost,
    energyCost,
    baseProductionCost,
    costWithFailure,
    netPrice,
    platformFeeAmount,
    finalSellingPrice,
    profitAmount
  };
};

