    isDirty: true,
    isCalculating: false,
    selectedPlatform: PLATFORM_PRESETS.find(p => p.percentage === initialInputs.platformPercentage && p.fixedFee === initialInputs.platformFixedFee)?.name || 'Personalizado',
    calcKey: 0
  });

  const [showToast, setShowToast] = useState(false);
  const [activeDetail, setActiveDetail] = useState<string | null>(null);
  const location = useLocation();

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.inputs));
  }, [state.inputs]);

  const handleCalculate = useCallback(() => {
    dispatch({ type: 'START_CALCULATION' });
    requestAnimationFrame(() => {
      setTimeout(() => {
        const results = runCalculation(state.inputs);
        dispatch({ type: 'FINISH_CALCULATION', results });
      }, 150);
    });
  }, [state.inputs]);

  const handleReset = useCallback(() => {
    if (confirm('Deseja realmente resetar todos os valores para o padrão?')) {
      dispatch({ 
        type: 'RESET', 
        defaultInputs: DEFAULT_INPUTS, 
        defaultPlatform: PLATFORM_PRESETS[0].name 
      });
    }
  }, []);

  const handleInputChange = useCallback((field: keyof CalculationInputs, value: number) => {
    dispatch({ type: 'UPDATE_INPUT', field, value });
  }, []);

  const handlePlatformChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => {
    const presetName = e.target.value;
    const preset = PLATFORM_PRESETS.find(p => p.name === presetName);
    if (preset) {
      dispatch({ 
        type: 'SET_PLATFORM', 
        name: presetName, 
        percentage: preset.percentage, 
        fixedFee: preset.fixedFee 
      });
    }
  }, []);

  const handleShare = useCallback(() => {
    if (!state.results) return;
    const text = `📊 *Orçamento de Impressão 3D*\n\n` +
      `🔹 *Peso:* ${state.inputs.weightGrams}g\n` +
      `🔹 *Tempo:* ${state.inputs.printTimeHours}h\n` +
      `🔹 *Custo Produção:* ${formatBRL(state.results.costWithFailure)}\n` +
      `💰 *Preço Sugerido:* ${formatBRL(state.results.finalSellingPrice)}\n\n` +
      `Gerado por Calc3D`;

    navigator.clipboard.writeText(text).then(() => {
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    });
  }, [state.results, state.inputs]);

  const handleExportCSV = useCallback(() => {
    if (!state.results) return;
    const rows = [
      ['Descricao', 'Valor'],
      ['Peso da Peca (g)', state.inputs.weightGrams],
      ['Tempo de Impressao (h)', state.inputs.printTimeHours],
      ['Taxa de Falha (%)', state.inputs.failureRate],
      ['Custo de Material (R$)', state.results.materialCost.toFixed(2)],
      ['Custo de Energia (R$)', state.results.energyCost.toFixed(2)],
      ['Custo de Embalagem (R$)', state.inputs.packagingCost.toFixed(2)],
      ['Custos Avulsos (R$)', state.inputs.extraCosts.toFixed(2)],
      ['Custo Total c/ Falhas (R$)', state.results.costWithFailure.toFixed(2)],
      ['Comissao Plataforma (%)', state.inputs.platformPercentage],
      ['Taxa Fixa Plataforma (R$)', state.inputs.platformFixedFee.toFixed(2)],
      ['Valor das Taxas (R$)', state.results.platformFeeAmount.toFixed(2)],
      ['Lucro Liquido (R$)', state.results.profitAmount.toFixed(2)],
      ['Preco Final de Venda (R$)', state.results.finalSellingPrice.toFixed(2)]
    ];
    const csvContent = "data:text/csv;charset=utf-8," + rows.map(e => e.join(",")).join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `orcamento_3d_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [state.results, state.inputs]);

  const chartData = useMemo(() => {
    if (!state.results) return [];
    return [
      { id: 'material', name: 'Material', value: state.results.materialCost, color: '#3b82f6' },
      { id: 'energia', name: 'Energia', value: state.results.energyCost, color: '#f59e0b' },
      { id: 'embalagem', name: 'Embalagem', value: state.inputs.packagingCost, color: '#10b981' },
      { id: 'extras', name: 'Extras', value: state.inputs.extraCosts, color: '#6366f1' },
      { id: 'falhas', name: 'Falhas', value: state.results.costWithFailure - state.results.baseProductionCost, color: '#ef4444' },
      { id: 'taxas', name: 'Taxas', value: state.results.platformFeeAmount, color: '#94a3b8' },
      { id: 'lucro', name: 'Lucro', value: state.results.profitAmount, color: '#8b5cf6' },
    ].filter(item => item.value > 0);
  }, [state.results, state.inputs]);

  const getCalculationSteps = (id: string) => {
    if (!state.results) return [];
    const { inputs, results } = state;

    switch (id) {
      case 'material':
        return [
          { label: 'Peso em Kilos', value: `${inputs.weightGrams}g / 1000 = ${inputs.weightGrams / 1000}kg`, desc: 'Primeiro transformamos o peso em gramas para quilos.' },
          { label: 'Custo Material', value: `${inputs.weightGrams / 1000}kg * ${formatBRL(inputs.pricePerKilo)} = ${formatBRL(results.materialCost)}`, desc: 'Multiplicamos o peso em quilos pelo valor do rolo de 1kg.' }
        ];
      case 'energia':
        return [
          { label: 'Consumo em kW', value: `${inputs.powerConsumptionWatts}W / 1000 = ${inputs.powerConsumptionWatts / 1000}kW`, desc: 'Convertemos a potência da impressora de Watts para Quilowatts.' },
          { label: 'Energia Total', value: `${inputs.printTimeHours}h * ${inputs.powerConsumptionWatts / 1000}kW = ${(inputs.printTimeHours * inputs.powerConsumptionWatts / 1000).toFixed(2)}kWh`, desc: 'Multiplicamos o tempo de uso pelo consumo horário.' },
          { label: 'Custo Energia', value: `${(inputs.printTimeHours * inputs.powerConsumptionWatts / 1000).toFixed(2)}kWh * ${formatBRL(inputs.energyCostKwh)} = ${formatBRL(results.energyCost)}`, desc: 'Multiplicamos o consumo total pela tarifa da sua conta de luz.' }
        ];
      case 'falhas':
        return [
          { label: 'Custo Produção', value: formatBRL(results.baseProductionCost), desc: 'Soma de material, energia, embalagem e extras.' },
          { label: 'Fator de Segurança', value: `1 - (${inputs.failureRate}% / 100) = ${(1 - inputs.failureRate / 100).toFixed(2)}`, desc: 'Calculamos quanto resta de eficiência após descontar as falhas.' },
          { label: 'Custo Real', value: `${formatBRL(results.baseProductionCost)} / ${(1 - inputs.failureRate / 100).toFixed(2)} = ${formatBRL(results.costWithFailure)}`, desc: 'Dividimos o custo pelo fator para diluir o prejuízo das peças ruins nas boas.' }
        ];
      case 'taxas':
        const netRequired = results.netPrice + inputs.platformFixedFee;
        const platformDivisor = (1 - inputs.platformPercentage / 100).toFixed(2);
        return [
          { label: 'Valor que Você Quer (Líquido)', value: formatBRL(results.netPrice), desc: 'Este é o valor que você deseja receber após todas as taxas (Custo + Lucro).' },
          { label: 'Somar Taxa Fixa', value: `${formatBRL(results.netPrice)} + ${formatBRL(inputs.platformFixedFee)} = ${formatBRL(netRequired)}`, desc: 'Algumas plataformas cobram um valor fixo (ex: R$ 3,00) por venda concluída.' },
          { label: 'Divisor da Comissão', value: `1 - (${inputs.platformPercentage}% / 100) = ${platformDivisor}`, desc: 'Para que a plataforma tire a parte dela do TOTAL e você ainda receba o esperado, precisamos de um divisor matemático chamado "margem inversa".' },
          { label: 'Preço Final de Venda', value: `${formatBRL(netRequired)} / ${platformDivisor} = ${formatBRL(results.finalSellingPrice)}`, desc: 'Este é o preço que você deve anunciar. Quando a plataforma tirar os ${inputs.platformPercentage}% deste valor, sobrará exatamente o que você precisa.' },
          { label: 'Total para Plataforma', value: `${formatBRL(results.finalSellingPrice)} - ${formatBRL(results.netPrice)} = ${formatBRL(results.platformFeeAmount)}`, desc: 'Este é o valor total que a plataforma ficará (Comissão + Taxa Fixa).' }
        ];
      case 'lucro':
        return [
          { label: 'Custo de Produção (c/ falhas)', value: formatBRL(results.costWithFailure), desc: 'Quanto custa cada peça boa que sai da sua impressora.' },
          { label: 'Multiplicador de Lucro', value: `${inputs.profitMargin}% de Margem`, desc: 'Quanto você quer ganhar por cima do custo.' },
          { label: 'Lucro Líquido', value: `${formatBRL(results.costWithFailure)} * ${inputs.profitMargin}% = ${formatBRL(results.profitAmount)}`, desc: 'Dinheiro "limpo" que sobra para você reinvestir ou pagar seu tempo de trabalho.' }
        ];
      case 'embalagem':
        return [{ label: 'Custo Fixo', value: formatBRL(inputs.packagingCost), desc: 'Valor total gasto com caixa, plástico e etiqueta por unidade.' }];
      case 'extras':
        return [{ label: 'Custo Adicional', value: formatBRL(inputs.extraCosts), desc: 'Valor gasto com pós-processamento (tintas, lixas) ou parafusos e componentes.' }];
      default:
        return [];
    }
  };

  const renderCalculateButton = () => (
    <button 
      onClick={handleCalculate}
      disabled={state.isCalculating}
      className={`w-full flex items-center justify-center gap-3 py-5 rounded-2xl font-black text-lg transition-all shadow-xl active:scale-[0.98] ${
        state.isCalculating 
          ? 'bg-slate-700 text-slate-400 cursor-wait'
          : state.isDirty 
            ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-blue-900/40 animate-pulse' 
            : 'bg-slate-800 text-slate-400 cursor-default border border-slate-700'
      }`}
    >
      {state.isCalculating ? <Loader2 size={24} className="animate-spin" /> : <Play size={24} fill="currentColor" />}
      {state.isCalculating ? 'Calculando...' : state.results ? 'Atualizar Cálculo' : 'Calcular Preço'}
    </button>
  );

  const renderProductionSections = () => (
    <div className="space-y-6">
      <section className="bg-slate-900 p-6 rounded-2xl shadow-xl border border-slate-800 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between mb-6 border-b border-slate-800 pb-4">
          <div className="flex items-center gap-2">
            <Printer className="text-blue-500" size={20} />
            <h2 className="text-lg font-semibold text-white">Produção</h2>
          </div>
          <button onClick={handleReset} className="text-slate-500 hover:text-slate-300 transition-colors flex items-center gap-1 text-xs font-bold uppercase tracking-wider">
            <RotateCcw size={14} /> Resetar
          </button>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
          <InputField label="Peso da Peça" value={state.inputs.weightGrams} onChange={(v) => handleInputChange('weightGrams', v)} suffix="g" />
          <InputField 
            label="Preço Filamento (kg)" 
            value={state.inputs.pricePerKilo} 
            onChange={(v) => handleInputChange('pricePerKilo', v)} 
            prefix="R$" 
            tooltip="O custo do material é calculado dividindo o peso da peça (g) por 1000 para converter para quilos, e multiplicando pelo preço do rolo. Ex: 100g de um rolo de R$ 120 custam R$ 12."
          />
          <InputField label="Tempo Impressão" value={state.inputs.printTimeHours} onChange={(v) => handleInputChange('printTimeHours', v)} suffix="h" />
          <InputField label="Falha Estimada" value={state.inputs.failureRate} onChange={(v) => handleInputChange('failureRate', v)} suffix="%" />
        </div>
      </section>
      <section className="bg-slate-900 p-6 rounded-2xl shadow-xl border border-slate-800 animate-in fade-in slide-in-from-bottom-4 duration-500 delay-75">
        <div className="flex items-center gap-2 mb-6 border-b border-slate-800 pb-4">
          <Zap className="text-amber-500" size={20} />
          <h2 className="text-lg font-semibold text-white">Energia</h2>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
          <InputField label="Potência (Watts)" value={state.inputs.powerConsumptionWatts} onChange={(v) => handleInputChange('powerConsumptionWatts', v)} suffix="W" />
          <InputField label="Custo kWh" value={state.inputs.energyCostKwh} onChange={(v) => handleInputChange('energyCostKwh', v)} prefix="R$" />
        </div>
      </section>
      <div className="hidden lg:block pt-4">{renderCalculateButton()}</div>
    </div>
  );

  const renderSalesSections = () => {
    const isCustom = state.selectedPlatform === 'Personalizado';
    return (
      <div className="space-y-6">
        <section className="bg-slate-900 p-6 rounded-2xl shadow-xl border border-slate-800 animate-in fade-in slide-in-from-bottom-4 duration-500 overflow-hidden">
          <div className="flex items-center gap-2 mb-6 border-b border-slate-800 pb-4">
            <Package className="text-emerald-500" size={20} />
            <h2 className="text-lg font-semibold text-white">Vendas e Plataforma</h2>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-8">
            <InputField label="Embalagem" value={state.inputs.packagingCost} onChange={(v) => handleInputChange('packagingCost', v)} prefix="R$" />
            <InputField label="Custos Avulsos" value={state.inputs.extraCosts} onChange={(v) => handleInputChange('extraCosts', v)} prefix="R$" />
          </div>
          <div className="border-t border-slate-800 pt-6">
            <label className="text-xs font-bold text-slate-500 block mb-3 uppercase tracking-widest">Canal de Venda</label>
            <div className="relative mb-6 group">
              <select value={state.selectedPlatform} onChange={handlePlatformChange} className="w-full bg-slate-800 border border-slate-700 text-white rounded-lg py-3.5 px-4 text-sm focus:ring-2 focus:ring-blue-500 outline-none appearance-none cursor-pointer transition-all hover:border-slate-600 hover:bg-slate-800/80 shadow-sm">
                {PLATFORM_PRESETS.map(p => <option key={p.name} value={p.name}>{p.name}</option>)}
              </select>
              <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500 transition-transform group-hover:translate-x-0.5"><ChevronRight className="rotate-90" size={16} /></div>
            </div>
            <div className={`relative overflow-hidden rounded-xl transition-all duration-500 cubic-bezier(0.4, 0, 0.2, 1) ${isCustom ? 'p-5 sm:p-6 bg-blue-600/10 border border-blue-500/40 shadow-[0_0_40px_rgba(59,130,246,0.1)] scale-[1.01] mt-2 mb-4' : 'p-0 bg-transparent border border-transparent scale-100'}`}>
              <div className={`grid grid-cols-1 sm:grid-cols-2 gap-5 sm:gap-6 relative z-10 transition-all duration-500 ${isCustom ? 'opacity-100 translate-y-0 visible' : 'opacity-80'}`}>
                {isCustom && <div className="sm:col-span-2 flex flex-wrap items-center justify-between gap-2 border-b border-blue-500/20 pb-4 mb-1"><div className="flex items-center gap-2 text-blue-400 text-[11px] font-bold uppercase tracking-[0.1em]"><Settings2 size={13} /> Configuração Manual</div></div>}
                <InputField label="Comissão (%)" value={state.inputs.platformPercentage} onChange={(v) => handleInputChange('platformPercentage', v)} suffix="%" step={0.1} />
                <InputField label="Taxa Fixa" value={state.inputs.platformFixedFee} onChange={(v) => handleInputChange('platformFixedFee', v)} prefix="R$" step={0.5} />
              </div>
            </div>
          </div>
        </section>
        <section className="bg-slate-900 p-6 rounded-2xl shadow-xl border border-slate-800 animate-in fade-in slide-in-from-bottom-4 duration-500 delay-75">
          <div className="flex items-center gap-2 mb-6 border-b border-slate-800 pb-4">
            <TrendingUp className="text-violet-500" size={20} />
            <h2 className="text-lg font-semibold text-white">Margem de Lucro</h2>
          </div>
          <div className="px-2">
            <div className="flex justify-between items-center mb-6">
              <span className="text-sm text-slate-400">Sobre custo de produção</span>
              <span className="text-3xl font-black text-blue-400 tracking-tighter">{state.inputs.profitMargin}%</span>
            </div>
            <input type="range" min="0" max="400" step="5" value={state.inputs.profitMargin} onChange={(e) => handleInputChange('profitMargin', parseInt(e.target.value))} className="w-full h-2.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500" />
          </div>
        </section>
        <div className="lg:hidden pb-4">{renderCalculateButton()}</div>
      </div>
    );
  };

  const renderResultSidebar = () => {
    if (!state.results) {
      return (
        <div className="flex flex-col items-center justify-center h-full bg-slate-900/50 border border-dashed border-slate-800 rounded-3xl p-12 text-center animate-in fade-in duration-700">
          <div className="bg-slate-800 p-6 rounded-full text-slate-600 mb-6"><Calculator size={48} /></div>
          <h3 className="text-xl font-bold text-slate-400 mb-2">Aguardando Cálculo</h3>
          <p className="text-slate-500 text-sm max-w-[240px]">Preencha os dados e clique no botão para visualizar a sugestão de preço.</p>
          <div className="mt-8 lg:hidden w-full">{renderCalculateButton()}</div>
        </div>
      );
    }

    const detailSteps = activeDetail ? getCalculationSteps(activeDetail) : [];
    const detailTitle = activeDetail ? (chartData.find(d => d.id === activeDetail)?.name || (activeDetail === 'taxas' ? 'Taxas' : 'Custo')) : '';

    return (
      <div key={state.calcKey} className="space-y-6 h-full animate-in fade-in slide-in-from-right-4 duration-500 relative">
        <CalculationDetailModal 
          isOpen={!!activeDetail}
          onClose={() => setActiveDetail(null)}
          title={detailTitle}
          steps={detailSteps}
        />

        {state.isDirty && (
          <div className="absolute top-0 left-1/2 -translate-x-1/2 -translate-y-4 z-20">
            <span className="bg-amber-500 text-slate-950 text-[10px] font-black uppercase px-3 py-1 rounded-full shadow-lg shadow-amber-900/30 flex items-center gap-1">
              <AlertTriangle size={10} /> Valores desatualizados
            </span>
          </div>
        )}

        {showToast && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] animate-in fade-in zoom-in slide-in-from-top-4 duration-300">
            <div className="bg-emerald-500 text-white px-6 py-3 rounded-2xl shadow-2xl shadow-emerald-900/40 flex items-center gap-3 border border-emerald-400/30">
              <div className="bg-white/20 p-1.5 rounded-lg"><ClipboardCheck size={20} /></div>
              <div className="flex flex-col">
                <span className="text-sm font-black uppercase tracking-wider">Copiado!</span>
                <span className="text-[10px] text-emerald-50 opacity-80">Orçamento na área de transferência.</span>
              </div>
            </div>
          </div>
        )}

        <div className="bg-blue-600 text-white p-8 rounded-[2.5rem] shadow-2xl shadow-blue-900/40 border border-blue-500/30 relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity"><Sparkles size={140} /></div>
          <div className="relative z-10">
            <p className="text-blue-100/70 text-xs font-bold uppercase tracking-[0.2em] mb-3">Preço Sugerido</p>
            <h3 className="text-5xl font-black mb-8 tracking-tighter transition-all duration-500 hover:scale-105 origin-left">
              <AnimatedCurrency value={state.results.finalSellingPrice} />
            </h3>
            <div className="space-y-4 pt-6 border-t border-blue-400/30 text-sm">
              <div className="flex justify-between transition-all duration-300 hover:translate-x-1">
                <span className="text-blue-100/70">Produção + Falhas</span>
                <span className="font-bold tabular-nums"><AnimatedCurrency value={state.results.costWithFailure} /></span>
              </div>
              <div className="flex justify-between transition-all duration-300 hover:translate-x-1">
                <span className="text-blue-100/70">Lucro Líquido</span>
                <span className="font-bold text-blue-50 tabular-nums"><AnimatedCurrency value={state.results.profitAmount} /></span>
              </div>
              <div className="flex justify-between items-center transition-all duration-300 hover:translate-x-1 group/fee">
                <div className="flex items-center gap-2">
                  <span className="text-blue-100/70">Taxas Canal</span>
                  <button 
                    onClick={() => setActiveDetail('taxas')}
                    className="p-1 rounded-md bg-blue-700/50 hover:bg-white hover:text-blue-600 text-blue-200 transition-all flex items-center gap-1.5 text-[10px] font-black uppercase border border-blue-400/20"
                  >
                    <HelpCircle size={12} /> Detalhes
                  </button>
                </div>
                <span className="font-bold tabular-nums"><AnimatedCurrency value={state.results.platformFeeAmount} /></span>
              </div>
            </div>
            <div className="mt-8 grid grid-cols-2 gap-3">
              <button onClick={handleShare} className="bg-blue-700/40 hover:bg-blue-700/60 backdrop-blur-sm p-4 rounded-2xl border border-blue-400/20 flex flex-col items-center gap-2 transition-all active:scale-95 group/btn">
                <Share2 className="text-blue-200 group-hover/btn:scale-110 transition-transform" size={20} />
                <span className="text-[10px] font-bold uppercase tracking-widest">Compartilhar</span>
              </button>
              <button onClick={() => window.print()} className="bg-blue-700/40 hover:bg-blue-700/60 backdrop-blur-sm p-4 rounded-2xl border border-blue-400/20 flex flex-col items-center gap-2 transition-all active:scale-95 group/btn">
                <FileText className="text-blue-200 group-hover/btn:scale-110 transition-transform" size={20} />
                <span className="text-[10px] font-bold uppercase tracking-widest">Imprimir</span>
              </button>
              <button onClick={handleExportCSV} className="bg-blue-700/40 hover:bg-blue-700/60 backdrop-blur-sm p-4 rounded-2xl border border-blue-400/20 flex flex-col items-center gap-2 transition-all active:scale-95 col-span-2 group/btn">
                <Table className="text-blue-200 group-hover/btn:scale-110 transition-transform" size={20} />
                <span className="text-[10px] font-bold uppercase tracking-widest">Exportar Planilha (CSV)</span>
              </button>
            </div>
          </div>
        </div>

        <div className="bg-slate-900 p-6 rounded-2xl shadow-xl border border-slate-800">
          <div className="flex items-center justify-between mb-6">
            <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2"><Info size={14} /> Distribuição de Custos</h4>
          </div>
          <div className="h-60 w-full mb-8">
            <ResponsiveContainer width="100%" height="100%">
              <RePieChart>
                <Pie data={chartData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={4} dataKey="value" stroke="none" animationDuration={1000}>
                  {chartData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                </Pie>
                <RechartsTooltip formatter={(v: number) => formatBRL(v)} contentStyle={{ backgroundColor: '#0f172a', borderRadius: '12px', border: '1px solid #1e293b', color: '#f1f5f9' }} />
              </RePieChart>
            </ResponsiveContainer>
          </div>
          <div className="grid grid-cols-1 gap-2 mb-4">
            {chartData.map((item) => (
              <div key={item.name} className="flex items-center justify-between text-[11px] p-2.5 rounded-xl bg-slate-800/40 border border-slate-800/60 transition-all hover:bg-slate-800/80 group/row">
                <div className="flex items-center gap-2">
                  <div className="w-2.5 h-2.5 rounded-full shadow-sm" style={{ backgroundColor: item.color }}></div>
                  <span className="text-slate-300 font-semibold">{item.name}</span>
                </div>
                <div className="flex items-center gap-3">
                  <span className="font-bold text-slate-100 tabular-nums"><AnimatedCurrency value={item.value} /></span>
                  <button 
                    onClick={() => setActiveDetail(item.id || '')}
