            <div key={idx} className="relative pl-8 animate-in slide-in-from-left duration-500" style={{ animationDelay: `${idx * 100}ms` }}>
              {idx !== steps.length - 1 && (
                <div className="absolute left-[15px] top-8 bottom-[-24px] w-0.5 bg-slate-800" />
              )}
              <div className="absolute left-0 top-0 w-8 h-8 rounded-full bg-blue-600/20 border border-blue-500/30 flex items-center justify-center text-blue-400 text-xs font-black z-10">
                {idx + 1}
              </div>
              <div className="bg-slate-800/40 p-4 rounded-2xl border border-slate-800">
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">{step.label}</p>
                <div className="font-mono text-sm text-blue-100 mb-2 p-3 bg-slate-950 rounded-xl border border-blue-500/10">
                  {step.value}
                </div>
                <p className="text-xs text-slate-400 leading-relaxed">{step.desc}</p>
              </div>
            </div>
          ))}
        </div>
        <div className="p-6 bg-slate-800/30 flex justify-end border-t border-slate-800">
          <button 
            onClick={onClose}
            className="w-full px-10 py-4 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-black transition-all text-sm shadow-lg shadow-blue-900/20 flex items-center justify-center gap-2"
          >
            Fechar Explicação <Check size={18} />
          </button>
        </div>
      </div>
    </div>
  );
};

/**
 * Pure calculation logic optimized for performance
 */
const runCalculation = (inputs: CalculationInputs): CalculationResults => {
  const materialCost = (inputs.weightGrams / 1000) * inputs.pricePerKilo;
  const energyCost = (inputs.printTimeHours * (inputs.powerConsumptionWatts / 1000)) * inputs.energyCostKwh;
  const baseProductionCost = materialCost + energyCost + inputs.packagingCost + inputs.extraCosts;

  const failureRateDecimal = inputs.failureRate / 100;
  const costWithFailure = failureRateDecimal >= 1 
    ? baseProductionCost * 2 
    : baseProductionCost / (1 - failureRateDecimal);

  const netPrice = costWithFailure * (1 + (inputs.profitMargin / 100));
  const profitAmount = netPrice - costWithFailure;

  const platformFeeDecimal = inputs.platformPercentage / 100;
  const finalSellingPrice = platformFeeDecimal >= 1 
    ? netPrice + inputs.platformFixedFee 
    : (netPrice + inputs.platformFixedFee) / (1 - platformFeeDecimal);

  const platformFeeAmount = finalSellingPrice - netPrice;

  return {
    materialCost,
    energyCost,
    baseProductionCost,
    costWithFailure,
    netPrice,
    platformFeeAmount,
    finalSellingPrice,
    profitAmount
  };
};

