    isDirty: true,
    isCalculating: false,
    selectedPlatform: PLATFORM_PRESETS.find(p => p.percentage === initialInputs.platformPercentage && p.fixedFee === initialInputs.platformFixedFee)?.name || 'Personalizado',
    calcKey: 0
  });

