            <tr><td className="p-4">Custos Avulsos</td><td className="p-4 text-right">{formatBRL(state.inputs.extraCosts)}</td></tr>
            <tr className="bg-slate-50 font-bold"><td className="p-4">Total com Falhas e Margem</td><td className="p-4 text-right">{formatBRL(state.results.netPrice)}</td></tr>
          </tbody>
        </table>
        <div className="flex justify-end pt-4 border-t-4 border-blue-600"><span className="text-3xl font-black">TOTAL: {formatBRL(state.results.finalSellingPrice)}</span></div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 selection:bg-blue-500 selection:text-white">
      {renderPrintableInvoice()}
