          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 pb-32 lg:pb-8 no-print">
        <div className="hidden lg:grid grid-cols-3 gap-8">
          <div className="col-span-2 space-y-6">{renderProductionSections()}{renderSalesSections()}</div>
          <div className="col-span-1">{renderResultSidebar()}</div>
        </div>
        <div className="lg:hidden">
          <Routes>
            <Route path="/" element={renderProductionSections()} />
            <Route path="/vendas" element={renderSalesSections()} />
            <Route path="/resultado" element={renderResultSidebar()} />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </div>
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-slate-900/80 backdrop-blur-xl border-t border-slate-800 p-2 lg:hidden z-50 shadow-2xl no-print">
        <div className="max-w-lg mx-auto">
          <div className="flex items-center justify-between px-4 py-2 mb-2 bg-slate-800/50 rounded-xl border border-slate-700/50 overflow-hidden relative">
            <div className="flex flex-col relative z-10">
              <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Sugerido</span>
              <span className="text-lg font-black text-blue-400 tracking-tighter tabular-nums">
                {state.results ? <AnimatedCurrency value={state.results.finalSellingPrice} /> : '--'}
              </span>
            </div>
            {location.pathname !== '/resultado' ? (
              <NavLink to="/resultado" className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg text-xs font-bold shadow-lg shadow-blue-900/40 hover:bg-blue-500 active:scale-95 transition-all relative z-10">Ver Detalhes <ChevronRight size={14} /></NavLink>
            ) : (
              <div className="flex gap-2 relative z-10">
                <button 
                  onClick={handleSave} 
                  disabled={saveStatus !== 'idle'}
                  className={`p-2 rounded-lg transition-all active:scale-90 flex items-center justify-center min-w-[36px] ${
                    saveStatus === 'saved' ? 'bg-emerald-500 text-white' : 'bg-slate-700 text-white'
                  }`}
                >
                  {saveStatus === 'saved' ? <Check size={16} className="animate-in zoom-in" /> : saveStatus === 'saving' ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                </button>
                <button onClick={handleShare} disabled={!state.results} className="bg-slate-700 text-white p-2 rounded-lg transition-all active:scale-90"><Share2 size={16} /></button>
                <button onClick={handleExportCSV} disabled={!state.results} className="bg-slate-700 text-white p-2 rounded-lg transition-all active:scale-90"><Table size={16} /></button>
                <button onClick={() => state.results && window.print()} disabled={!state.results} className={`text-white px-4 py-2 rounded-lg text-xs font-bold shadow-lg transition-all flex items-center gap-2 ${state.results ? 'bg-emerald-600 shadow-emerald-900/40 active:scale-95' : 'bg-slate-700 opacity-50 cursor-not-allowed'}`}><FileText size={14} /> Imprimir</button>
              </div>
            )}
            {state.isDirty && state.results && <div className="absolute inset-0 bg-amber-500/5 pointer-events-none animate-pulse" />}
          </div>
          <div className="flex justify-around items-center pt-1 pb-1">
            <NavLink to="/" className={({ isActive }) => `flex flex-col items-center gap-1 p-2 transition-all ${isActive ? 'text-blue-400 scale-110' : 'text-slate-500'}`}><Printer size={22} /><span className="text-[10px] font-bold uppercase tracking-tighter">Produção</span></NavLink>
            <NavLink to="/vendas" className={({ isActive }) => `flex flex-col items-center gap-1 p-2 transition-all ${isActive ? 'text-emerald-400 scale-110' : 'text-slate-500'}`}><Wallet size={22} /><span className="text-[10px] font-bold uppercase tracking-tighter">Vendas</span></NavLink>
            <NavLink to="/resultado" className={({ isActive }) => `flex flex-col items-center gap-1 p-2 transition-all ${isActive ? 'text-violet-400 scale-110' : 'text-slate-500'}`}><div className="relative"><LayoutDashboard size={22} />{state.isDirty && state.results && <div className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-amber-500 rounded-full border-2 border-slate-900 animate-pulse" />}</div><span className="text-[10px] font-bold uppercase tracking-tighter">Resumo</span></NavLink>
          </div>
        </div>
      </nav>
    </div>
  );
};

const App: React.FC = () => (
