            <NavLink to="/" className={({ isActive }) => `flex flex-col items-center gap-1 p-2 transition-all ${isActive ? 'text-blue-400 scale-110' : 'text-slate-500'}`}><Printer size={22} /><span className="text-[10px] font-bold uppercase tracking-tighter">Projeto</span></NavLink>
