            <NavLink to="/resultado" className={({ isActive }) => `flex flex-col items-center gap-1 p-2 transition-all ${isActive ? 'text-blue-500 scale-110' : 'text-slate-500'}`}><LayoutDashboard size={22} /><span className="text-[10px] font-black uppercase">Resumo</span></NavLink>
          </div>
        </div>
      </nav>
    </div>
  );
};

