      `💰 *Preço Sugerido:* ${formatBRL(state.results.finalSellingPrice)}\n\n` +
      `Gerado por Calc3D`;
    navigator.clipboard.writeText(text).then(() => {
      triggerToast("Copiado!", "Orçamento na área de transferência.", <ClipboardCheck className="text-white" size={20} />);
    });
