      const net = state.results.netPrice;
      const feeFixed = state.inputs.platformFixedFee;
      const feePerc = state.inputs.platformPercentage;
      const factor = (1 - (feePerc / 100)).toFixed(4);

      return [
        { 
          label: "1. Valor Pretendido (Líquido)", 
          value: `Preço Líquido (R$ ${net.toFixed(2)}) + Taxa Fixa (R$ ${feeFixed.toFixed(2)}) = R$ ${(net + feeFixed).toFixed(2)}`, 
          desc: "Este é o valor que você deseja que 'sobre' na sua mão antes da plataforma tirar a porcentagem dela, somado à taxa obrigatória por venda." 
        },
        { 
          label: "2. Fator de Marketplace (Inversão de Margem)", 
          value: `Fator = 1 - (Comissão / 100)\nFator = 1 - (${feePerc} / 100) = ${factor}`, 
          desc: "A plataforma cobra comissão sobre o PREÇO FINAL. Para garantir que seu lucro não seja 'comido', precisamos dividir o valor pelo que resta da porcentagem (Ex: se a taxa é 10%, dividimos por 0.90)." 
        },
        { 
          label: "3. Cálculo do Preço de Anúncio", 
          value: `Preço de Venda = Valor Pretendido / Fator\nPreço de Venda = ${(net + feeFixed).toFixed(2)} / ${factor}\nPreço de Venda = R$ ${state.results.finalSellingPrice.toFixed(2)}`, 
          desc: "Dividindo o valor pretendido pelo fator, chegamos ao preço exato que deve ser anunciado. Assim, quando a plataforma descontar a comissão, você receberá exatamente o valor esperado." 
        },
        {
          label: "Resumo para Iniciantes",
          value: "Fórmula de Markup de Marketplace",
          desc: "Se você anunciar por R$ 100 com 10% de taxa, ganha R$ 90. Mas se o seu custo + lucro for R$ 100, você NÃO PODE anunciar por R$ 110 (ganharia R$ 99). Usando nossa fórmula acima, você descobre o preço real de anúncio para nunca ter prejuízo!"
        }
      ];
    }

    return [
      { 
        label: "Custo de Material", 
        value: `(${state.results.totalWeight}g / 1000) * ${formatBRL(state.inputs.pricePerKilo)}`, 
        desc: "Peso total das partes multiplicado pelo preço do quilo do filamento." 
